let notes = [{ id: 1, text: 'Learn Node' }]
let nextId = 2

function handle(method, path, body) {
  const [, resource, id] = path.split('/')
  if (resource !== 'notes') return { status: 404, body: { error: 'Not found' } }

  if (method === 'GET' && !id) return { status: 200, body: notes }
  if (method === 'POST') {
    const note = { id: nextId++, text: body.text }
    notes.push(note)
    return { status: 201, body: note }
  }
  const note = notes.find((n) => n.id === Number(id))
  if (!note) return { status: 404, body: { error: 'No such note' } }
  if (method === 'GET') return { status: 200, body: note }
  if (method === 'DELETE') {
    notes = notes.filter((n) => n !== note)
    return { status: 204, body: null }
  }
  return { status: 405, body: { error: 'Method not allowed' } }
}

console.log(handle('POST', '/notes', { text: 'Build an API' }))
console.log(handle('GET', '/notes'))
console.log(handle('DELETE', '/notes/1'))
console.log(handle('GET', '/notes/1'))

